import {articleTags,articleLocation} from './observatorio-discovery.mjs';
export function followsArticle(article,rows){return rows.some(r=>r.kind==='topic'?(article.topics||[]).includes(r.value):r.kind==='tag'?articleTags(article).includes(r.value):r.kind==='place'&&articleLocation(article)?.label===r.value);}
export function createFollows({db,enabled=true,onChange=()=>{},onStatus=()=>{}}){
 let uid=null,epoch=0,revision=0,rows=[],loaded=false,pending=new Set();
 const emit=()=>onChange({uid,rows:[...rows],loaded,pending:[...pending]});
 async function refresh(){if(!uid||pending.size)return;const token=epoch,rev=revision,user=uid;try{const {data,error}=await db.from('atlas_dev_news_follows').select('kind,value').eq('user_id',user);if(token!==epoch||rev!==revision)return;if(error)throw error;rows=data||[];loaded=true;emit();onStatus('Seguimientos guardados en tu cuenta · disponibles en PC y móvil.');}catch{if(token===epoch)onStatus('No se pudieron cargar tus seguimientos. Reintenta con conexión.');}}
 async function session(user){const next=enabled&&user&&!user.is_anonymous?user.id:null;if(next===uid)return;epoch++;uid=next;rows=[];loaded=false;pending=new Set();emit();if(uid)await refresh();else onStatus('Ingresa con Convergencia para seguir hashtags, lugares y temas.');}
 async function toggle(kind,value){if(!uid||!loaded)return false;const key=kind+':'+value;if(pending.has(key))return false;const token=epoch,user=uid,remove=rows.some(r=>r.kind===kind&&r.value===value);revision++;pending.add(key);emit();onStatus('Guardando seguimiento…');try{const query=remove?db.from('atlas_dev_news_follows').delete().eq('user_id',user).eq('kind',kind).eq('value',value):db.from('atlas_dev_news_follows').insert({kind,value});const {error}=await query;if(token!==epoch)return false;if(error&&error.code!=='23505')throw error;rows=rows.filter(r=>r.kind!==kind||r.value!==value);if(!remove)rows.push({kind,value});onStatus('Seguimiento actualizado en tu cuenta.');return true;}catch{if(token===epoch)onStatus('No se pudo guardar. Tu seguimiento anterior se conserva; reintenta con conexión.');return false;}finally{if(token===epoch){pending.delete(key);emit();}}}
 return {session,refresh,toggle,get rows(){return rows;}};
}
